with ins as (insert into public.artist_press (artist_id,artist_slug,title,publication,url,date_published,type) select a.id,x.s,x.t,x.p,x.u,x.d::date,'feature' from json_to_recordset('[{"s":"sodhi","t":"Celtronic and Boxout.fm present Delhi-Derry Together in Sound","p":"British Council Northern Ireland blog","u":"https://nireland.britishcouncil.org/blog/celtronic-and-boxoutfm-present-delhi-derry-together-sound","d":"2022-06-29"},{"s":"sunju-hargun","t":"Karmic conspiracy: Bangkok''s DJ Sunju Hargun","p":"Khaosod English","u":"https://www.khaosodenglish.com/featured/2017/04/07/karmic-conspiracy-bangkoks-dj-sunju-hargun/","d":"2017-04-07"}]'::json) as x(s text,t text,p text,u text,d text) join public.artists a on a.slug=x.s on conflict (artist_slug,url) do nothing returning 1) select count(*) from ins;